#!/usr/bin/env python3
"""Differential checks for the two exact components of the toolkit.

`state.Machine.prepare` must minimise `(cost, commands, command sequence)`
exactly, and `regex.Pattern` must decide the documented restricted grammar.
Both are compared here against independent references: an exhaustive search
over all simple paths, and Python's `re` fed a translated pattern.  The tests
import the package directly, so run them from anywhere:

    python3 tests/differential.py
"""
import random
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))

from eywa.regex import compile_pattern
from eywa.state import Machine

ALPHABET = ["a", "b", "c", "x", ".", "\\", "[", "]", "(", ")", "|", "*", "-"]


def brute_force(transitions, initial, target, enabled):
    """Exhaustive `(cost, commands, command sequence)` over simple paths."""
    best = None
    stack = [(initial, 0, 0, [], frozenset([initial]))]
    while stack:
        state, cost, count, commands, seen = stack.pop()
        if state == target:
            candidate = (cost, count, list(commands))
            if best is None or candidate < best:
                best = candidate
            continue
        for index, transition in enumerate(transitions):
            if transition["from"] != state or not enabled[index]:
                continue
            if transition["to"] in seen:
                continue
            stack.append((transition["to"], cost + transition["cost"], count + 1,
                          commands + [transition["command"]],
                          seen | {transition["to"]}))
    return best


def check_preparation(trials=200):
    rng = random.Random(20240607)
    for _ in range(trials):
        states = ["s%d" % index for index in range(rng.randint(2, 5))]
        transitions = []
        pairs = set()
        for _ in range(rng.randint(1, 12)):
            while True:
                source = rng.choice(states)
                command = "c%d" % rng.randint(0, 5)
                if (source, command) not in pairs:
                    pairs.add((source, command))
                    break
            transitions.append({"from": source, "to": rng.choice(states),
                                "command": command, "cost": rng.randint(1, 6),
                                "when": None})
        machine = Machine({"states": states, "initial": rng.choice(states),
                           "state_param": "st", "message_param": "msg",
                           "transitions": transitions})
        enabled = [rng.random() < 0.75 for _ in transitions]
        target = rng.choice(states)
        got = machine.prepare(target, enabled)
        want = brute_force(transitions, machine.initial, target, enabled)
        if want is None:
            assert got is None, (transitions, enabled, got)
        else:
            assert got == (want[0], want[2]), (transitions, enabled, got, want)
    return trials


def to_python(node):
    """Translate a toolkit pattern AST into an equivalent Python regex."""
    name = node.__class__.__name__
    if name == "Empty":
        return ""
    if name == "Range":
        if node.low == node.high:
            return re.escape(node.low)
        return "[%s-%s]" % (re.escape(node.low), re.escape(node.high))
    if name == "Choice":
        return "(" + "|".join(to_python(sub) for sub in node.exprs) + ")"
    if name == "Seq":
        return "".join(to_python(sub) for sub in node.exprs)
    if name == "Star":
        return "(" + to_python(node.expr) + ")*"
    raise AssertionError(name)


def random_pattern(rng, depth=0):
    choice = rng.randint(0, 5 if depth < 3 else 2)
    if choice == 0:
        char = rng.choice("abc.*[]()|\\-")
        source = "\\" + char if char in ".*[]()|\\" else char
        return source, re.escape(char)
    if choice == 1:
        items = []
        for _ in range(rng.randint(1, 3)):
            if rng.random() < 0.4:
                low, high = sorted(rng.sample(list("abcxyz"), 2))
                items.append(re.escape(low) + "-" + re.escape(high)
                             if rng.random() < 0.5 else re.escape(low))
            else:
                items.append(re.escape(rng.choice("abcxyz")))
        return "[" + "".join(items) + "]", "[" + "".join(items) + "]"
    if choice == 2:
        return "", ""
    if choice == 3:
        parts = [random_pattern(rng, depth + 1) for _ in range(rng.randint(2, 3))]
        return ("(" + "|".join(part[0] for part in parts) + ")",
                "(" + "|".join(part[1] for part in parts) + ")")
    if choice == 4:
        parts = [random_pattern(rng, depth + 1) for _ in range(rng.randint(1, 3))]
        return ("".join(part[0] for part in parts),
                "".join(part[1] for part in parts))
    inner = random_pattern(rng, depth + 1)
    return "(" + inner[0] + ")*", "(" + inner[1] + ")*"


def check_patterns(trials=800):
    rng = random.Random(1729)
    checked = 0
    for _ in range(trials):
        source, python = random_pattern(rng)
        if len(source) > 128:
            continue
        pattern = compile_pattern(source)
        reference = re.compile("(?s:" + python + ")\\Z")
        for _ in range(8):
            text = "".join(rng.choice(ALPHABET)
                           for _ in range(rng.randint(0, 6)))
            assert pattern.matches(text) == (reference.match(text) is not None), \
                (source, python, text)
            checked += 1
    return checked


def main():
    trials = check_preparation()
    print("PASS preparation matches exhaustive search on %d machines" % trials)
    checked = check_patterns()
    print("PASS patterns match the reference on %d strings" % checked)
    return 0


if __name__ == "__main__":
    sys.exit(main())
